ATED_BY,												LAST_UPDATE_DATE,												LAST_UPDATE_BY,																								discount				)				VALUES(										'" . $_POST['FRANCHISEE_CODE'] . "',										'" . $_POST['FRANCHISEE_NAME'] . "',										'" . $_POST['TYPE'] . "',										'" . $_POST['ADRESS'] . "',										'" . $_POST['PHONE'] . "',										'" . $_POST['MAIL'] . "',										'" . $_POST['WE_CHAT'] . "',										'" . $_POST['CHUANGZHEN'] . "',										'" . $_POST['APPLICANT'] . "',										'" . $_POST['APPLICANT_ID'] . "',																			'" . $_POST['SHOP_AREA'] . "',										'" . $_POST['SHOP_TYPE'] . "',										'" . $time . "',										'" . $_SESSION['UserID'] . "',										'" . $time . "',										'" . $_SESSION['UserID'] . "',																				'" . $_POST['discount'] . "'				)";				        $result = DB_query($sql, $db);				        prnMsg(_('新增加盟商成功！！！'), 'success');				        unset($_POST);    }}?>    <p class="page_title_text"><img src="<?php echo $RootPath; ?>/css/<?php echo $Theme; ?>//images/maintenance.png" title="新增加盟商" alt="新增加盟商">新增加盟商</p>    <form action="<?php echo htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8'); ?>" method ="POST" enctype="multipart/form-data">        <div>            <input type="hidden" name="FormID" value = "<?php echo $_SESSION['FormID']; ?>">            <br>            <table class="selection">                <tr>                    <td>加盟商编码：</td>                    <td><input type="text" required="required"  id="FRANCHISEE_CODE" size="30"  name="FRANCHISEE_CODE"  ></td>                    <td>加盟商名称：</td>                    <td><input type="text" required="required"  id="FRANCHISEE_NAME" size="30" name="FRANCHISEE_NAME"  ></td>                </tr>                <tr>                    <td>门店类别：</td>                    <td>                        <select name="TYPE" id="TYPE">                            <option>    </option>                            <option>直营店</option>                            <option>加盟店</option>    